42	//
43	// The command runs with its working directory set to the converter's temporary
44	// directory so that pandoc resolves the relative image paths emitted by the
45	// HTML stage against the copies placed there by copyImages. A reference document
46	// with bordered tables is generated and applied when possible.
47	func (c *Converter) convertDOCX(htmlPath, docxPath string) error {
48		pandoc, err := c.findPandoc()
49		if err != nil {
50			return err
51		}
52	
