99	// path. The returned document is passed to pandoc via --reference-doc.
100	func (c *Converter) buildReferenceDoc(pandoc string) (string, error) {
101		cmd := exec.Command(pandoc, "--print-default-data-file", "reference.docx") //nolint:gosec
102		var stdout, stderr bytes.Buffer
103		cmd.Stdout = &stdout
104		cmd.Stderr = &stderr
105		if err := cmd.Run(); err != nil {
106			return "", fmt.Errorf("read default reference: %w\n%s", err, stderr.String())
107		}
108	
109		patched, err := addTableBorders(stdout.Bytes())
