116			return "", fmt.Errorf("write reference doc: %w", err)
117		}
118		return refPath, nil
119	}
120	
121	// addTableBorders rewrites the word/styles.xml entry of a reference.docx so the
122	// default Table style carries visible borders, returning the new archive bytes.
123	func addTableBorders(docx []byte) ([]byte, error) {
124		zr, err := zip.NewReader(bytes.NewReader(docx), int64(len(docx)))
125		if err != nil {
126			return nil, fmt.Errorf("open reference zip: %w", err)
127		}
128	
129		var buf bytes.Buffer
130		zw := zip.NewWriter(&buf)
131		for _, f := range zr.File {
132			if err := copyZipEntry(zw, f); err != nil {
133				return nil, err
134			}
135		}
136		if err := zw.Close(); err != nil {
137			return nil, fmt.Errorf("finalize reference zip: %w", err)
138		}
139		return buf.Bytes(), nil
