1	// Package converter orchestrates the Markdown → HTML → PDF pipeline.
2	//
3	// The pipeline consists of three stages:
4	//  1. Parse Markdown and extract fenced Mermaid code blocks.
5	//  2. Render each Mermaid block to an SVG file using the mmdc CLI.
6	//  3. Build a self-contained GitHub-styled HTML file and print it to PDF
7	//     using a headless Chromium browser (via the Playwright Python driver).
8	package converter
9	
10	import (
11		"fmt"
12		"io"
13		"net/url"
14		"os"
15		"os/exec"
16		"path/filepath"
17		"regexp"
18		"strings"
19	)
20	
21	// Config holds all runtime options for the converter.
22	type Config struct {
23		// InputFile is the path to the source Markdown file.
24		InputFile string
25		// OutputFile is the destination output path (PDF or DOCX).
26		OutputFile string
27		// Format selects the output format: "pdf" (default) or "docx".
28		// An empty value is treated as "pdf".
29		Format string
30		// FontRegular is the file path to the Noto Sans CJK JP Regular font.
31		FontRegular string
32		// FontBold is the file path to the Noto Sans CJK JP Bold font.
33		FontBold string
34		// FontMedium is the file path to the Noto Sans CJK JP Medium font.
35		FontMedium string
36		// MmdcPath is the path to the mmdc (Mermaid CLI) binary.
37		MmdcPath string
38		// PandocPath is the path to the pandoc binary used for DOCX output.
39		// When empty, md2pdf auto-detects pandoc on PATH and in common locations.
40		PandocPath string
41		// PythonPath is the path to the Python 3 interpreter used to drive Playwright.
42		// When empty, md2pdf auto-detects an interpreter on PATH that can import the
43		// playwright package.
44		PythonPath string
45		// PuppeteerConfig is an optional path to a Puppeteer JSON config file
46		// passed to mmdc via its -p flag. When empty the converter auto-generates
47		// a temporary config pointing at the system Chromium.
48		PuppeteerConfig string
49		// PageSize controls the PDF paper size (A4, Letter, A3).
50		PageSize string
51		// MarginTop, MarginBottom, MarginLeft, MarginRight set PDF page margins.
52		MarginTop    string
53		MarginBottom string
54		MarginLeft   string
55		MarginRight  string
56		// Verbose enables detailed progress logging.
57		Verbose bool
58	}
59	
60	// Converter manages the conversion lifecycle including temporary file cleanup.
61	type Converter struct {
62		cfg     *Config
63		workDir string // temporary directory for intermediate files
64	}
65	
66	// New creates a new Converter and prepares a temporary working directory.
67	func New(cfg *Config) (*Converter, error) {
68		work, err := os.MkdirTemp("", "md2pdf-*")
69		if err != nil {
70			return nil, fmt.Errorf("create temp dir: %w", err)
71		}
72		return &Converter{cfg: cfg, workDir: work}, nil
73	}
74	
75	// Close removes the temporary working directory and all intermediate files.
76	func (c *Converter) Close() {
77		_ = os.RemoveAll(c.workDir)
78	}
79	
80	// Convert runs the full Markdown → PDF pipeline for the given input file,
81	// writing the result to outputPath.
82	func (c *Converter) Convert(inputPath, outputPath string) error {
83		mdBytes, err := os.ReadFile(inputPath)
84		if err != nil {
85			return fmt.Errorf("read input: %w", err)
86		}
87	
88		c.logf("Parsing Markdown and extracting Mermaid blocks...")
89		doc, err := parseMarkdown(mdBytes)
90		if err != nil {
91			return fmt.Errorf("parse markdown: %w", err)
92		}
93	
94		c.logf("Rendering %d Mermaid diagram(s)...", len(doc.mermaidBlocks))
95		if err := c.renderMermaid(doc); err != nil {
96			return fmt.Errorf("render mermaid: %w", err)
97		}
98	
99		c.logf("Building HTML...")
100		htmlPath := filepath.Join(c.workDir, "document.html")
101		if err := c.buildHTML(doc, htmlPath); err != nil {
102			return fmt.Errorf("build html: %w", err)
103		}
104	
105		c.logf("Copying images to working directory...")
106		srcDir, err := filepath.Abs(filepath.Dir(inputPath))
107		if err != nil {
108			return fmt.Errorf("resolve input dir: %w", err)
109		}
110		if err := c.copyImages(doc.HTML, srcDir); err != nil {
111			return fmt.Errorf("copy images: %w", err)
112		}
113	
114		absOut, err := filepath.Abs(outputPath)
115		if err != nil {
116			return fmt.Errorf("resolve output path: %w", err)
117		}
118	
119		switch strings.ToLower(c.cfg.Format) {
120		case "docx":
121			c.logf("Converting to DOCX with pandoc...")
122			if err := c.convertDOCX(htmlPath, absOut); err != nil {
123				return fmt.Errorf("convert docx: %w", err)
124			}
125		default:
126			c.logf("Printing PDF with headless Chromium...")
127			if err := c.printPDF(htmlPath, absOut); err != nil {
128				return fmt.Errorf("print pdf: %w", err)
129			}
130		}
131	
132		return nil
133	}
134	
135	// logf prints a formatted message when verbose mode is enabled.
136	func (c *Converter) logf(format string, args ...any) {
137		if c.cfg.Verbose {
138			fmt.Printf("  "+format+"\n", args...)
139		}
140	}
141	
142	// imgSrcRe matches src attributes in <img> tags.
143	var imgSrcRe = regexp.MustCompile(`<img\s[^>]*?\bsrc=["']([^"']+)["']`)
144	
145	// copyImages scans rendered HTML for <img> tags with relative paths and copies
146	// the referenced files from srcDir into the working directory, preserving the
147	// relative directory structure so that the HTML can reference them as-is.
148	func (c *Converter) copyImages(html, srcDir string) error {
149		matches := imgSrcRe.FindAllStringSubmatch(html, -1)
150		for _, m := range matches {
151			src := m[1]
152	
153			// Skip absolute URLs and data URIs.
154			if strings.HasPrefix(src, "http://") || strings.HasPrefix(src, "https://") || strings.HasPrefix(src, "data:") {
155				continue
156			}
157	
158			// Skip diagrams md2pdf generated itself; they already live in the
159			// working directory and have no counterpart in the source tree.
160			if strings.HasPrefix(src, mermaidImageSubdir+"/") {
161				continue
162			}
163	
164			// Decode percent-encoded paths (e.g. spaces as %20).
165			decoded, err := url.PathUnescape(src)
166			if err != nil {
167				decoded = src
168			}
169	
170			// Skip absolute file paths.
171			if filepath.IsAbs(decoded) {
172				continue
173			}
174	
175			origPath := filepath.Clean(filepath.Join(srcDir, decoded))
176			destPath := filepath.Clean(filepath.Join(c.workDir, decoded))
177	
178			// Prevent path traversal outside the source or working directory.
179			if !strings.HasPrefix(origPath+string(os.PathSeparator), srcDir+string(os.PathSeparator)) {
180				c.logf("  warning: image path escapes source directory: %s", decoded)
181				continue
182			}
183			if !strings.HasPrefix(destPath+string(os.PathSeparator), c.workDir+string(os.PathSeparator)) {
184				c.logf("  warning: image path escapes work directory: %s", decoded)
185				continue
186			}
187	
188			if _, err := os.Stat(origPath); err != nil {
189				c.logf("  warning: image not found: %s", origPath)
190				continue
191			}
192	
193			if err := os.MkdirAll(filepath.Dir(destPath), 0o755); err != nil {
194				return fmt.Errorf("create image dir: %w", err)
195			}
196			if err := copyFile(origPath, destPath); err != nil {
197				return fmt.Errorf("copy %s: %w", decoded, err)
198			}
199			c.logf("  copied image: %s", decoded)
200		}
201		return nil
202	}
203	
204	// copyFile copies the file at src to dst.
205	func copyFile(src, dst string) error {
206		in, err := os.Open(src)
207		if err != nil {
208			return err
209		}
210		defer in.Close()
211	
212		out, err := os.Create(dst)
213		if err != nil {
214			return err
215		}
216		defer out.Close()
217	
218		if _, err := io.Copy(out, in); err != nil {
219			return err
220		}
221		return out.Close()
222	}
223	
224	// chromiumPath attempts to locate the system Chromium executable.
225	// It checks common Linux paths and falls back to whatever Playwright ships.
226	func chromiumPath() (string, error) {
227		// Honour CHROME_PATH if set. Fail fast on invalid values.
228		if p := os.Getenv("CHROME_PATH"); p != "" {
229			info, err := os.Stat(p)
230			if err != nil {
231				return "", fmt.Errorf("CHROME_PATH is set but invalid: %w", err)
232			}
233			if info.IsDir() {
234				return "", fmt.Errorf("CHROME_PATH points to a directory: %s", p)
235			}
236			if info.Mode()&0o111 == 0 {
237				return "", fmt.Errorf("CHROME_PATH is not executable: %s", p)
238			}
239			return p, nil
240		}
241	
242		candidates := []string{
243			// Linux (CI / Playwright)
244			"/opt/pw-browsers/chromium-1194/chrome-linux/chrome",
245			"/usr/bin/chromium-browser",
246			"/usr/bin/chromium",
247			"/usr/bin/google-chrome",
248		}
249	
250		// macOS: Playwright cache.
251		if home, err := os.UserHomeDir(); err == nil {
252			cacheDir := filepath.Join(home, "Library", "Caches", "ms-playwright")
253			if entries, err := os.ReadDir(cacheDir); err == nil {
254				for _, e := range entries {
255					if !e.IsDir() {
256						continue
257					}
258					macBin := filepath.Join(cacheDir, e.Name(), "chrome-mac", "Chromium.app", "Contents", "MacOS", "Chromium")
259					if _, err := os.Stat(macBin); err == nil {
260						candidates = append([]string{macBin}, candidates...)
261						break
262					}
263				}
264			}
265		}
266	
267		// macOS: common install locations.
268		candidates = append(candidates,
269			"/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
270			"/Applications/Chromium.app/Contents/MacOS/Chromium",
271		)
272	
273		for _, p := range candidates {
274			if _, err := os.Stat(p); err == nil {
275				return p, nil
276			}
277		}
278	
279		// Last resort: ask the shell.
280		for _, name := range []string{"chromium-browser", "chromium", "google-chrome"} {
281			if out, err := exec.LookPath(name); err == nil {
282				return out, nil
283			}
284		}
285		return "", fmt.Errorf("no Chromium executable found; install chromium-browser or set CHROME_PATH")
286	}
