// Package converter orchestrates the Markdown → HTML → PDF pipeline.
//
// The pipeline consists of three stages:
//  1. Parse Markdown and extract fenced Mermaid code blocks.
//  2. Render each Mermaid block to an SVG file using the mmdc CLI.
//  3. Build a self-contained GitHub-styled HTML file and print it to PDF
//     using a headless Chromium browser (via the Playwright Python driver).
package converter

import (
	"fmt"
	"io"
	"net/url"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
)

// Config holds all runtime options for the converter.
type Config struct {
	// InputFile is the path to the source Markdown file.
	InputFile string
	// OutputFile is the destination output path (PDF or DOCX).
	OutputFile string
	// Format selects the output format: "pdf" (default) or "docx".
	// An empty value is treated as "pdf".
	Format string
	// FontRegular is the file path to the Noto Sans CJK JP Regular font.
	FontRegular string
	// FontBold is the file path to the Noto Sans CJK JP Bold font.
	FontBold string
	// FontMedium is the file path to the Noto Sans CJK JP Medium font.
	FontMedium string
	// MmdcPath is the path to the mmdc (Mermaid CLI) binary.
	MmdcPath string
	// PandocPath is the path to the pandoc binary used for DOCX output.
	// When empty, md2pdf auto-detects pandoc on PATH and in common locations.
	PandocPath string
	// PythonPath is the path to the Python 3 interpreter used to drive Playwright.
	// When empty, md2pdf auto-detects an interpreter on PATH that can import the
	// playwright package.
	PythonPath string
	// PuppeteerConfig is an optional path to a Puppeteer JSON config file
	// passed to mmdc via its -p flag. When empty the converter auto-generates
	// a temporary config pointing at the system Chromium.
	PuppeteerConfig string
	// PageSize controls the PDF paper size (A4, Letter, A3).
	PageSize string
	// MarginTop, MarginBottom, MarginLeft, MarginRight set PDF page margins.
	MarginTop    string
	MarginBottom string
	MarginLeft   string
	MarginRight  string
	// Verbose enables detailed progress logging.
	Verbose bool
}

// Converter manages the conversion lifecycle including temporary file cleanup.
type Converter struct {
	cfg     *Config
	workDir string // temporary directory for intermediate files
}

// New creates a new Converter and prepares a temporary working directory.
func New(cfg *Config) (*Converter, error) {
	work, err := os.MkdirTemp("", "md2pdf-*")
	if err != nil {
		return nil, fmt.Errorf("create temp dir: %w", err)
	}
	return &Converter{cfg: cfg, workDir: work}, nil
}

// Close removes the temporary working directory and all intermediate files.
func (c *Converter) Close() {
	_ = os.RemoveAll(c.workDir)
}

// Convert runs the full Markdown → PDF pipeline for the given input file,
// writing the result to outputPath.
func (c *Converter) Convert(inputPath, outputPath string) error {
	mdBytes, err := os.ReadFile(inputPath)
	if err != nil {
		return fmt.Errorf("read input: %w", err)
	}

	c.logf("Parsing Markdown and extracting Mermaid blocks...")
	doc, err := parseMarkdown(mdBytes)
	if err != nil {
		return fmt.Errorf("parse markdown: %w", err)
	}

	c.logf("Rendering %d Mermaid diagram(s)...", len(doc.mermaidBlocks))
	if err := c.renderMermaid(doc); err != nil {
		return fmt.Errorf("render mermaid: %w", err)
	}

	c.logf("Building HTML...")
	htmlPath := filepath.Join(c.workDir, "document.html")
	if err := c.buildHTML(doc, htmlPath); err != nil {
		return fmt.Errorf("build html: %w", err)
	}

	c.logf("Copying images to working directory...")
	srcDir, err := filepath.Abs(filepath.Dir(inputPath))
	if err != nil {
		return fmt.Errorf("resolve input dir: %w", err)
	}
	if err := c.copyImages(doc.HTML, srcDir); err != nil {
		return fmt.Errorf("copy images: %w", err)
	}

	absOut, err := filepath.Abs(outputPath)
	if err != nil {
		return fmt.Errorf("resolve output path: %w", err)
	}

	switch strings.ToLower(c.cfg.Format) {
	case "docx":
		c.logf("Converting to DOCX with pandoc...")
		if err := c.convertDOCX(htmlPath, absOut); err != nil {
			return fmt.Errorf("convert docx: %w", err)
		}
	default:
		c.logf("Printing PDF with headless Chromium...")
		if err := c.printPDF(htmlPath, absOut); err != nil {
			return fmt.Errorf("print pdf: %w", err)
		}
	}

	return nil
}

// logf prints a formatted message when verbose mode is enabled.
func (c *Converter) logf(format string, args ...any) {
	if c.cfg.Verbose {
		fmt.Printf("  "+format+"\n", args...)
	}
}

// imgSrcRe matches src attributes in <img> tags.
var imgSrcRe = regexp.MustCompile(`<img\s[^>]*?\bsrc=["']([^"']+)["']`)

// copyImages scans rendered HTML for <img> tags with relative paths and copies
// the referenced files from srcDir into the working directory, preserving the
// relative directory structure so that the HTML can reference them as-is.
func (c *Converter) copyImages(html, srcDir string) error {
	matches := imgSrcRe.FindAllStringSubmatch(html, -1)
	for _, m := range matches {
		src := m[1]

		// Skip absolute URLs and data URIs.
		if strings.HasPrefix(src, "http://") || strings.HasPrefix(src, "https://") || strings.HasPrefix(src, "data:") {
			continue
		}

		// Skip diagrams md2pdf generated itself; they already live in the
		// working directory and have no counterpart in the source tree.
		if strings.HasPrefix(src, mermaidImageSubdir+"/") {
			continue
		}

		// Decode percent-encoded paths (e.g. spaces as %20).
		decoded, err := url.PathUnescape(src)
		if err != nil {
			decoded = src
		}

		// Skip absolute file paths.
		if filepath.IsAbs(decoded) {
			continue
		}

		origPath := filepath.Clean(filepath.Join(srcDir, decoded))
		destPath := filepath.Clean(filepath.Join(c.workDir, decoded))

		// Prevent path traversal outside the source or working directory.
		if !strings.HasPrefix(origPath+string(os.PathSeparator), srcDir+string(os.PathSeparator)) {
			c.logf("  warning: image path escapes source directory: %s", decoded)
			continue
		}
		if !strings.HasPrefix(destPath+string(os.PathSeparator), c.workDir+string(os.PathSeparator)) {
			c.logf("  warning: image path escapes work directory: %s", decoded)
			continue
		}

		if _, err := os.Stat(origPath); err != nil {
			c.logf("  warning: image not found: %s", origPath)
			continue
		}

		if err := os.MkdirAll(filepath.Dir(destPath), 0o755); err != nil {
			return fmt.Errorf("create image dir: %w", err)
		}
		if err := copyFile(origPath, destPath); err != nil {
			return fmt.Errorf("copy %s: %w", decoded, err)
		}
		c.logf("  copied image: %s", decoded)
	}
	return nil
}

// copyFile copies the file at src to dst.
func copyFile(src, dst string) error {
	in, err := os.Open(src)
	if err != nil {
		return err
	}
	defer in.Close()

	out, err := os.Create(dst)
	if err != nil {
		return err
	}
	defer out.Close()

	if _, err := io.Copy(out, in); err != nil {
		return err
	}
	return out.Close()
}

// chromiumPath attempts to locate the system Chromium executable.
// It checks common Linux paths and falls back to whatever Playwright ships.
func chromiumPath() (string, error) {
	// Honour CHROME_PATH if set. Fail fast on invalid values.
	if p := os.Getenv("CHROME_PATH"); p != "" {
		info, err := os.Stat(p)
		if err != nil {
			return "", fmt.Errorf("CHROME_PATH is set but invalid: %w", err)
		}
		if info.IsDir() {
			return "", fmt.Errorf("CHROME_PATH points to a directory: %s", p)
		}
		if info.Mode()&0o111 == 0 {
			return "", fmt.Errorf("CHROME_PATH is not executable: %s", p)
		}
		return p, nil
	}

	candidates := []string{
		// Linux (CI / Playwright)
		"/opt/pw-browsers/chromium-1194/chrome-linux/chrome",
		"/usr/bin/chromium-browser",
		"/usr/bin/chromium",
		"/usr/bin/google-chrome",
	}

	// macOS: Playwright cache.
	if home, err := os.UserHomeDir(); err == nil {
		cacheDir := filepath.Join(home, "Library", "Caches", "ms-playwright")
		if entries, err := os.ReadDir(cacheDir); err == nil {
			for _, e := range entries {
				if !e.IsDir() {
					continue
				}
				macBin := filepath.Join(cacheDir, e.Name(), "chrome-mac", "Chromium.app", "Contents", "MacOS", "Chromium")
				if _, err := os.Stat(macBin); err == nil {
					candidates = append([]string{macBin}, candidates...)
					break
				}
			}
		}
	}

	// macOS: common install locations.
	candidates = append(candidates,
		"/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
		"/Applications/Chromium.app/Contents/MacOS/Chromium",
	)

	for _, p := range candidates {
		if _, err := os.Stat(p); err == nil {
			return p, nil
		}
	}

	// Last resort: ask the shell.
	for _, name := range []string{"chromium-browser", "chromium", "google-chrome"} {
		if out, err := exec.LookPath(name); err == nil {
			return out, nil
		}
	}
	return "", fmt.Errorf("no Chromium executable found; install chromium-browser or set CHROME_PATH")
}

package converter

import (
	"bytes"
	"fmt"
	"strings"

	"github.com/yuin/goldmark"
	"github.com/yuin/goldmark/ast"
	"github.com/yuin/goldmark/extension"
	"github.com/yuin/goldmark/parser"
	"github.com/yuin/goldmark/renderer/html"
	"github.com/yuin/goldmark/text"
)

// mermaidBlock holds the source text of a single Mermaid diagram and the SVG
// content that will replace it after rendering.
type mermaidBlock struct {
	// Source is the raw Mermaid diagram definition.
	Source string
	// SVGContent is populated after mmdc renders the diagram to SVG (PDF output).
	SVGContent string
	// ImagePath is the working-directory-relative path to a rendered raster
	// image (DOCX output). When set, the HTML builder emits an <img> tag
	// instead of inlining the SVG.
	ImagePath string
	// Placeholder is the unique HTML comment used to locate the block in the
	// rendered HTML so it can be swapped with the inline SVG.
	Placeholder string
}

// parsedDoc contains the Markdown rendered to HTML together with the list of
// Mermaid blocks that were extracted during parsing.
type parsedDoc struct {
	// HTML is the full Markdown rendered to HTML, with Mermaid code blocks
	// replaced by their unique placeholder comments.
	HTML string
	// mermaidBlocks is the ordered list of extracted Mermaid diagrams.
	mermaidBlocks []*mermaidBlock
}

// parseMarkdown converts raw Markdown bytes into a parsedDoc.
// Fenced code blocks with the language tag "mermaid" are extracted and
// replaced with placeholder comments so they can be swapped with SVG later.
func parseMarkdown(src []byte) (*parsedDoc, error) {
	md := goldmark.New(
		goldmark.WithExtensions(
			extension.GFM,
			extension.Table,
		),
		goldmark.WithParserOptions(
			parser.WithAutoHeadingID(),
		),
		goldmark.WithRendererOptions(
			html.WithHardWraps(),
			html.WithXHTML(),
			html.WithUnsafe(), // allow raw HTML pass-through
		),
	)

	reader := text.NewReader(src)
	doc := md.Parser().Parse(reader)

	var blocks []*mermaidBlock

	// Walk the AST to find fenced code blocks tagged as "mermaid".
	// We replace their source text with a placeholder before rendering.
	ast.Walk(doc, func(n ast.Node, entering bool) (ast.WalkStatus, error) {
		if !entering {
			return ast.WalkContinue, nil
		}
		cb, ok := n.(*ast.FencedCodeBlock)
		if !ok {
			return ast.WalkContinue, nil
		}
		lang := string(cb.Language(src))
		if !strings.EqualFold(lang, "mermaid") {
			return ast.WalkContinue, nil
		}

		// Extract diagram source.
		var buf bytes.Buffer
		for i := 0; i < cb.Lines().Len(); i++ {
			line := cb.Lines().At(i)
			buf.Write(line.Value(src))
		}

		idx := len(blocks)
		placeholder := fmt.Sprintf("MERMAID_PLACEHOLDER_%d", idx)
		block := &mermaidBlock{
			Source:      buf.String(),
			Placeholder: placeholder,
		}
		blocks = append(blocks, block)

		// Replace node content with a raw HTML node containing the placeholder.
		rawHTML := ast.NewRawHTML()
		seg := text.NewSegment(0, 0)
		rawHTML.Segments.Append(seg)

		// We cannot easily mutate the AST node here, so we rely on the
		// post-processing step in renderHTML() to swap fenced blocks.
		_ = rawHTML
		return ast.WalkContinue, nil
	})

	// Render the full document to HTML.
	var htmlBuf bytes.Buffer
	if err := md.Renderer().Render(&htmlBuf, src, doc); err != nil {
		return nil, fmt.Errorf("goldmark render: %w", err)
	}

	rendered := htmlBuf.String()

	// Replace each <pre><code class="language-mermaid">…</code></pre> block with
	// its placeholder comment so the HTML builder can inject the SVG later.
	for _, b := range blocks {
		rendered = replaceMermaidBlock(rendered, b.Source, b.Placeholder)
	}

	return &parsedDoc{
		HTML:          rendered,
		mermaidBlocks: blocks,
	}, nil
}

// replaceMermaidBlock scans rendered HTML for a <pre><code …mermaid…> block
// whose content matches src and replaces it with the placeholder comment.
// This is a targeted string replacement rather than a full HTML parse.
func replaceMermaidBlock(html, src, placeholder string) string {
	// goldmark renders fenced mermaid blocks as:
	//   <pre><code class="language-mermaid">…source…</code></pre>
	// We search for the pattern and replace the entire <pre>…</pre> element.
	escaped := htmlEscape(src)
	targets := []string{
		"<pre><code class=\"language-mermaid\">" + escaped + "</code></pre>",
		"<pre><code class=\"language-mermaid\">" + src + "</code></pre>",
	}
	comment := "<!--" + placeholder + "-->"
	for _, t := range targets {
		if idx := strings.Index(html, t); idx >= 0 {
			return html[:idx] + comment + html[idx+len(t):]
		}
	}
	return html
}

// htmlEscape escapes special HTML characters in s. The escape set must match
// goldmark's HTML renderer so that fenced code-block content can be located in
// the rendered output for placeholder substitution.
func htmlEscape(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	s = strings.ReplaceAll(s, "\"", "&quot;")
	return s
}

