1	package converter
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"os"
7		"os/exec"
8		"path/filepath"
9		"strings"
10	)
11	
12	// mermaidImageSubdir is the working-directory subdirectory that holds PNGs
13	// rendered for DOCX output. The unusual name keeps generated diagrams from
14	// colliding with user-supplied images copied by copyImages.
15	const mermaidImageSubdir = "_md2pdf_mermaid"
16	
17	// mermaidBackground is the background colour passed to mmdc for rendered diagrams.
18	const mermaidBackground = "white"
19	
20	// mermaidPNGScale scales raster (PNG) diagram output up so it stays sharp when
21	// embedded in a document.
22	const mermaidPNGScale = "2"
23	
24	// puppeteerConfig is the JSON structure written for mmdc's -p flag.
25	type puppeteerConfig struct {
26		ExecutablePath string   `json:"executablePath"`
27		Args           []string `json:"args"`
28	}
29	
30	// renderMermaid iterates over all Mermaid blocks in doc, writes each source to
31	// a .mmd temp file, invokes mmdc to produce an SVG, and stores the SVG content
32	// back into the block's SVGContent field.
33	func (c *Converter) renderMermaid(doc *parsedDoc) error {
34		if len(doc.mermaidBlocks) == 0 {
35			return nil
36		}
37	
38		pcfgPath, err := c.ensurePuppeteerConfig()
39		if err != nil {
40			return fmt.Errorf("puppeteer config: %w", err)
41		}
42	
43		// DOCX output embeds raster images, since Word cannot reliably display the
44		// inline/standalone SVG that pandoc produces from HTML. PDF output keeps the
45		// crisp inline SVG.
46		if strings.EqualFold(c.cfg.Format, "docx") {
47			for i, block := range doc.mermaidBlocks {
48				name, err := c.renderSingleDiagramPNG(i, block.Source, pcfgPath)
49				if err != nil {
50					return fmt.Errorf("diagram %d: %w", i, err)
51				}
52				block.ImagePath = name
53				c.logf("  diagram %d rendered to PNG (%s)", i, name)
54			}
55			return nil
56		}
57	
58		for i, block := range doc.mermaidBlocks {
59			svg, err := c.renderSingleDiagram(i, block.Source, pcfgPath)
60			if err != nil {
61				return fmt.Errorf("diagram %d: %w", i, err)
62			}
63			block.SVGContent = svg
64			c.logf("  diagram %d rendered (%d bytes)", i, len(svg))
65		}
66		return nil
67	}
68	
69	// renderSingleDiagramPNG writes the Mermaid source to a temp file, runs mmdc to
70	// produce a PNG inside the working directory, and returns the PNG's filename
71	// (relative to the working directory) for embedding as an <img>.
72	func (c *Converter) renderSingleDiagramPNG(idx int, source, puppeteerCfgPath string) (string, error) {
73		// Isolate generated diagrams in a dedicated subdirectory so they cannot be
74		// overwritten by user-supplied images that copyImages later copies into the
75		// working directory (e.g. a Markdown <img> referencing "diagram_0.png").
76		if err := os.MkdirAll(filepath.Join(c.workDir, mermaidImageSubdir), 0o755); err != nil {
77			return "", fmt.Errorf("create mermaid image dir: %w", err)
78		}
79	
80		mmdFile := filepath.Join(c.workDir, mermaidImageSubdir, fmt.Sprintf("diagram_%d.mmd", idx))
81		pngRel := filepath.ToSlash(filepath.Join(mermaidImageSubdir, fmt.Sprintf("diagram_%d.png", idx)))
82		pngFile := filepath.Join(c.workDir, filepath.FromSlash(pngRel))
83	
84		// Scale up so the raster diagram stays sharp in the document.
85		if err := c.runMmdc(mmdFile, pngFile, source, puppeteerCfgPath, "-s", mermaidPNGScale); err != nil {
86			return "", err
87		}
88		if _, err := os.Stat(pngFile); err != nil {
89			return "", fmt.Errorf("mmdc did not produce PNG output: %w", err)
90		}
91		return pngRel, nil
92	}
93	
94	// renderSingleDiagram writes the Mermaid source to a temp file, runs mmdc, and
95	// returns the resulting SVG bytes as a string.
96	func (c *Converter) renderSingleDiagram(idx int, source, puppeteerCfgPath string) (string, error) {
97		mmdFile := filepath.Join(c.workDir, fmt.Sprintf("diagram_%d.mmd", idx))
98		svgFile := filepath.Join(c.workDir, fmt.Sprintf("diagram_%d.svg", idx))
99	
100		if err := c.runMmdc(mmdFile, svgFile, source, puppeteerCfgPath); err != nil {
101			return "", err
102		}
103	
104		svgBytes, err := os.ReadFile(svgFile)
105		if err != nil {
106			return "", fmt.Errorf("read SVG output: %w", err)
107		}
108		return string(svgBytes), nil
109	}
110	
111	// runMmdc writes the Mermaid source to mmdFile and invokes mmdc to render it to
112	// outFile. extraArgs are appended after the standard flags (e.g. PNG scaling),
113	// and the Puppeteer config is passed when non-empty.
114	func (c *Converter) runMmdc(mmdFile, outFile, source, puppeteerCfgPath string, extraArgs ...string) error {
115		if err := os.WriteFile(mmdFile, []byte(source), 0o644); err != nil {
116			return fmt.Errorf("write .mmd file: %w", err)
117		}
118	
119		args := []string{"-i", mmdFile, "-o", outFile, "-b", mermaidBackground}
120		args = append(args, extraArgs...)
121		if puppeteerCfgPath != "" {
122			args = append(args, "-p", puppeteerCfgPath)
123		}
124	
125		cmd := exec.Command(c.resolveMmdc(), args...) //nolint:gosec
126		out, err := cmd.CombinedOutput()
127		if err != nil {
128			return fmt.Errorf("mmdc failed: %w\noutput: %s", err, out)
129		}
130		return nil
131	}
132	
133	// resolveMmdc returns the mmdc binary to invoke, honouring the configured path
134	// and resolving it against $PATH so the caller's environment is respected.
135	func (c *Converter) resolveMmdc() string {
136		mmdcBin := c.cfg.MmdcPath
137		if mmdcBin == "" {
138			mmdcBin = "mmdc"
139		}
140		if resolved, err := exec.LookPath(mmdcBin); err == nil {
141			mmdcBin = resolved
142		}
143		return mmdcBin
144	}
145	
146	// ensurePuppeteerConfig returns the path to a Puppeteer JSON config suitable
147	// for mmdc. If the user provided one via -puppeteer-config, it is used as-is;
148	// otherwise a temporary config pointing at the detected system Chromium is
149	// generated inside the working directory.
150	func (c *Converter) ensurePuppeteerConfig() (string, error) {
151		if c.cfg.PuppeteerConfig != "" {
152			return c.cfg.PuppeteerConfig, nil
153		}
154	
155		chromeExe, err := chromiumPath()
156		if err != nil {
157			return "", err
158		}
159	
160		cfg := puppeteerConfig{
161			ExecutablePath: chromeExe,
162			Args:           []string{"--no-sandbox", "--disable-setuid-sandbox"},
163		}
164		data, err := json.Marshal(cfg)
