    font-size: 1.85em;
    font-weight: 700;
    color: #1f2328;
    border-bottom: 2px solid #d0d7de;
    padding-bottom: 10px;
    margin-top: 32px;
    margin-bottom: 20px;
  }

  h2 {
    font-family: 'Noto Sans JP', sans-serif;
    font-size: 1.4em;
    font-weight: 700;
    color: #1f2328;
    border-bottom: 1px solid #d0d7de;
    padding-bottom: 7px;
    margin-top: 36px;
    margin-bottom: 16px;
  }

  h3 {
    font-family: 'Noto Sans JP', sans-serif;
    font-size: 1.15em;
    font-weight: 600;
    color: #1f2328;
    margin-top: 24px;
    margin-bottom: 10px;
  }

  h4, h5, h6 {
    font-family: 'Noto Sans JP', sans-serif;
    font-size: 1em;
    font-weight: 600;
    color: #1f2328;
    margin-top: 20px;
