    margin-bottom: 14px;
    color: #1f2328;
  }

  a { color: #0969da; text-decoration: none; }
  a:hover { text-decoration: underline; }

  blockquote {
    border-left: 4px solid #d0d7de;
    padding: 6px 16px;
    color: #656d76;
    background: #f6f8fa;
    margin: 14px 0;
    border-radius: 0 6px 6px 0;
  }
  blockquote p {
    margin-bottom: 0;
    color: #656d76;
    font-size: 13.5px;
    font-family: 'Noto Sans JP', sans-serif;
  }

  table {
    width: 100%;
    border-collapse: collapse;
    margin: 14px 0;
    font-size: 13.5px;
    font-family: 'Noto Sans JP', sans-serif;
  }
  th {
    background: #f6f8fa;
    font-weight: 600;
    text-align: left;
    padding: 8px 13px;
    border: 1px solid #d0d7de;
    color: #1f2328;
  }
  td {
    padding: 8px 13px;
    border: 1px solid #d0d7de;
    color: #1f2328;
  }
  tr:nth-child(even) td { background: #f6f8fa; }

  code {
    font-family: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
    font-size: 85%;
    background: rgba(175, 184, 193, 0.2);
    padding: 2px 5px;
    border-radius: 5px;
    color: #1f2328;
  }

  pre {
    background: #f6f8fa;
    border: 1px solid #d0d7de;
    border-radius: 6px;
    padding: 16px;
    overflow-x: auto;
    margin: 14px 0;
  }
  pre code {
    background: none;
    padding: 0;
    font-size: 13px;
    line-height: 1.5;
  }

  ul, ol {
    padding-left: 2em;
    margin-bottom: 14px;
    font-family: 'Noto Sans JP', sans-serif;
  }
  li { margin-bottom: 5px; }

  hr {
    border: none;
    border-top: 1px solid #d0d7de;
    margin: 28px 0;
  }

  strong { font-weight: 700; }
  em     { font-style: italic; }

  img {
    max-width: 100%;
    height: auto;
  }

  /* Mermaid diagram container */
  .diagram-wrapper {
    background: #f6f8fa;
    border: 1px solid #d0d7de;
    border-radius: 8px;
    padding: 20px;
    margin: 16px 0;
    text-align: center;
    overflow: hidden;
  }
  .diagram-wrapper svg {
    max-width: 100%;
    height: auto;
    display: block;
    margin: 0 auto;
  }
`

// firstHeading extracts the text content of the first <h1> element from the
// rendered HTML, used as the document title.
func (d *parsedDoc) firstHeading() string {
	html := d.HTML
	start := strings.Index(html, "<h1")
	if start < 0 {
		return ""
	}
	tagEnd := strings.Index(html[start:], ">")
	if tagEnd < 0 {
		return ""
	}
	inner := html[start+tagEnd+1:]
	end := strings.Index(inner, "</h1>")
	if end < 0 {
		return ""
	}
	// Strip any inner tags (e.g. anchor links added by goldmark).
	raw := inner[:end]
	result := strings.Builder{}
	inTag := false
	for _, r := range raw {
		switch {
		case r == '<':
			inTag = true
		case r == '>':
			inTag = false
		case !inTag:
			result.WriteRune(r)
		}
	}
	return strings.TrimSpace(result.String())
}

